INSERT INTO changelog (title, body, created_at) VALUES ('Після аудиту: коротше і видно головне', 'Центр: зверху «Зараз важливо» — 3 пункти, що горять (поломки продуктів, борги, червоні тривоги клієнтів, прострочене, Підтверди), клік веде одразу куди треба. «Промпт: виправити все це» тепер короткий (~1,5k символів замість 33k): помилки згруповані за причиною, P0/P1/P2, без паспорта — Claude Code бачить репо. Секрет вебхука на «Звʼязок» і в «Продажах» більше не показується на екрані (тільки ••••, кнопка копіювати). Звʼязок → Події: щоденні usage/health/insight тільки лічильником. Підтверди: схожі пропозиції склеюються, що висить понад 3 дні — знімається; прохання клієнтів з них стають однією задачею «Розібрати прохання клієнта з переписки».', datetime('now'));
